"""CLI: render a domain template into a candidate fact batch (data/candidates/)."""

from __future__ import annotations

import argparse
import logging
import sys
from pathlib import Path

import yaml

from xlmem.benchmark.templates import TemplateError, load_and_render

logging.basicConfig(level=logging.INFO, format="[%(levelname)s] %(message)s")
logger = logging.getLogger("render_facts")

HEADER = """\
# CANDIDATE fact batch -- NOT part of the production fact bank.
#
# Rendered from {template} with {entities} by
# `python -m xlmem.scripts.render_facts`. Do not edit by hand: fix the template
# and re-render. No facts were generated by a model under test.
#
# NOT bilingually reviewed (BENCHMARK_SPEC.md Section 7.4). Review the template
# and value lexicon, then merge into data/facts_v1.yaml.
"""


def main() -> int:
    parser = argparse.ArgumentParser(description="Render a domain template into candidate facts.")
    parser.add_argument("--template", required=True, help="Domain template YAML.")
    parser.add_argument("--entities", default="data/templates/entities.yaml")
    parser.add_argument("--out", required=True, help="Output candidate YAML (must not exist).")
    parser.add_argument(
        "--batch", type=int, default=1,
        help="Write only plan entries with this `batch:` (default 1; entries without one are "
        "batch 1). The whole plan is still rendered, so uniqueness holds across batches.",
    )
    args = parser.parse_args()

    out = Path(args.out)
    if out.exists():
        logger.error("Refusing to overwrite %s; delete it first if re-rendering is intended.", out)
        return 1

    try:
        facts = load_and_render(args.template, args.entities)
    except TemplateError as e:
        logger.error("Template error: %s", e)
        return 1
    with open(args.template, encoding="utf-8") as f:
        plan = yaml.safe_load(f)["facts"]
    in_batch = {p["id"] for p in plan if p.get("batch", 1) == args.batch}
    facts = [fact for fact in facts if fact["id"] in in_batch]
    if not facts:
        logger.error("No plan entries with batch %d in %s", args.batch, args.template)
        return 1

    body = yaml.safe_dump(
        {"version": "1.0", "facts": facts}, allow_unicode=True, sort_keys=False, width=1000
    )
    out.write_text(HEADER.format(template=args.template, entities=args.entities) + body, "utf-8")
    logger.info("Rendered %d facts to %s", len(facts), out)
    return 0


if __name__ == "__main__":
    sys.exit(main())
